/*
 * ZERO_PAGE - clear one physical page through the AST_$ZERO_BUFF window
 *
 * Original address: 0x00E00EB0 (SAU2 map: inside "I E00BE8 AST_", between
 * AST_$WAIT_FOR_AST_INTRANS and AST_$PAGE_ZERO; module-local, so the name
 * carries no `$` and the file lives in misc/ per CLAUDE.md)
 * Size: 60 bytes (0x00E00EB0 .. 0x00E00EEB)
 * Generated by: Claude Opus 5.5
 *
 * Compiled Pascal (link/unlk, stack arguments), not hand assembly.
 * Callers: AST_$PAGE_ZERO (0x00E00F02) and three AST paging routines
 * (0x00E02E1C, 0x00E030AA, 0x00E03636).
 *
 * Frame (link.w A6,-0xc): (0x8,A6) ppn.
 *
 * Blocks:
 *   0x00E00EB4-0x00E00EC8  MMU_$INSTALL(ppn, 0xFF8C00 = AST_$ZERO_BUFF, 0x16)
 *                          (`pea (0x16).w`, the flags longword)
 *   0x00E00ECC-0x00E00EDA  move.w #0xff / dbf: 256 `clr.l (A0)+`, the 1KB
 *                          window
 *   0x00E00EDE-0x00E00EE2  MMU_$REMOVE(ppn)
 */

#include "mmu/mmu.h"
#include "ast/ast.h"

void ZERO_PAGE(uint32_t ppn)
{
    uint32_t *p;        /* A0 */
    int16_t count;      /* D0w */

    /* 0x00E00EB4-0x00E00EC8 */
    MMU_$INSTALL(ppn, ARCH_PTR_TO_VA(AST_$ZERO_BUFF), 0x16);

    /* 0x00E00ECC-0x00E00EDA */
    p = AST_$ZERO_BUFF;
    count = 0xFF;
    do {
        *p++ = 0;
    } while (--count != -1);

    /* 0x00E00EDE-0x00E00EE2 */
    MMU_$REMOVE(ppn);
}
